// BOTÃO 1 DA LIÇÃO: TEXTO BÍBLICO & CRONOLOGIA (Apenas leitura e linha do tempo, sem botões cruzados)
window.openLessonReaderScreen = function() {
  if (typeof playClick === "function") playClick();
  window.EBD_STATE.lessonReturnContext = true;
  window.renderLessonReaderScreen();
  if (typeof showScreen === "function") showScreen("screen-lesson-reader");
};

window.renderLessonReaderScreen = function() {
  const lesson = window.getCurrentLessonObj();
  const ageData = (lesson.byAge && lesson.byAge[window.EBD_STATE.ageBracket]) || lesson.byAge["6-8"];

  const titleEl = document.getElementById("reader-lesson-title");
  const eraEl = document.getElementById("reader-era-pill");
  const imgEl = document.getElementById("reader-lesson-img");
  const bodyEl = document.getElementById("reader-lesson-body");
  const verseEl = document.getElementById("reader-lesson-verse");
  const chronoEl = document.getElementById("reader-chrono-connection");

  if (titleEl) titleEl.textContent = `Semana ${lesson.week} • ${lesson.title}`;
  if (eraEl) eraEl.textContent = `${lesson.eraName} • ${lesson.chronologyDate} (${lesson.bibleRef})`;
  if (imgEl) imgEl.src = lesson.thumbImg;
  if (bodyEl) bodyEl.textContent = ageData.text;
  if (verseEl) verseEl.textContent = `"${ageData.verse}"`;
  if (chronoEl) chronoEl.textContent = lesson.chronologyConnection;

  const progressEl = document.getElementById("reader-chrono-progress-bar");
  if (progressEl) {
    progressEl.innerHTML = window.EBD_LESSONS_CURRICULUM.map(l => {
      const active = l.week === lesson.week;
      const passed = l.week < lesson.week;
      return `<div class="chrono-step-dot ${active ? "active" : ""} ${passed ? "passed" : ""}" title="Semana ${l.week}: ${l.title}">${l.week}</div>`;
    }).join("");
  }
};

// BOTÃO 2 DA LIÇÃO: HISTÓRIA COM O VOVÔ NÉSIO (Voz oficial Arturo Casares + 4 Cenas Ilustradas 3D)
window.openVovoStoryScreen = function() {
  if (typeof playClick === "function") playClick();
  window.stopVovoStoryNarration();
  window.EBD_STATE.lessonReturnContext = true;
  window.EBD_STATE.vovoActiveSceneIdx = 0;

  const lesson = window.getCurrentLessonObj();
  const titleEl = document.getElementById("vovo-story-title");
  const textEl = document.getElementById("vovo-story-text");
  const statusEl = document.getElementById("vovo-audio-status");

  if (titleEl) titleEl.textContent = `Semana ${lesson.week} • ${lesson.title}`;
  if (textEl) textEl.textContent = lesson.vovoStoryScript;
  if (statusEl) statusEl.textContent = "Toque em 'Ouvir a Voz do Vovô Nésio' para escutar a história completa!";

  window.renderVovoStoryScene(0);
  if (typeof showScreen === "function") showScreen("screen-vovo-story");
};

window.renderVovoStoryScene = function(sceneIdx) {
  const lesson = window.getCurrentLessonObj();
  const scenes = lesson.storyScenes || [{ img: lesson.thumbImg, caption: lesson.title }];
  const idx = Math.max(0, Math.min(sceneIdx, scenes.length - 1));
  window.EBD_STATE.vovoActiveSceneIdx = idx;

  const imgEl = document.getElementById("vovo-story-scene-img");
  const capEl = document.getElementById("vovo-story-scene-caption");
  const dotsEl = document.getElementById("vovo-story-scene-dots");

  if (imgEl && scenes[idx]) imgEl.src = scenes[idx].img;
  if (capEl && scenes[idx]) capEl.textContent = scenes[idx].caption;

  if (dotsEl) {
    dotsEl.innerHTML = scenes.map((sc, i) =>
      `<button type="button" class="vovo-scene-pill ${i === idx ? "active" : ""}" onclick="renderVovoStoryScene(${i})">Cena ${i + 1}</button>`
    ).join("");
  }
};

window._vovoPreloadedCache = window._vovoPreloadedCache || {};

window.preloadVovoLessonImages = function(lessonObj) {
  const lesson = lessonObj || window.getCurrentLessonObj();
  if (!lesson || !lesson.storyScenes) return;
  lesson.storyScenes.forEach(sc => {
    if (!sc || !sc.img) return;
    const baseSrc = String(sc.img).split("?")[0] + "?v=78";
    if (!window._vovoPreloadedCache[baseSrc]) {
      const im = new Image();
      im.decoding = "async";
      im.src = baseSrc;
      window._vovoPreloadedCache[baseSrc] = im;
    }
  });
};

window.formatVovoTime = function(sec) {
  const s = Math.max(0, Math.floor(Number(sec) || 0));
  const m = Math.floor(s / 60);
  const r = String(s % 60).padStart(2, "0");
  return `${m}:${r}`;
};

window.getVovoSceneIndexForProgress = function(lesson, progress) {
  const scenes = (lesson && lesson.storyScenes) || [];
  if (!scenes.length) return 0;
  const p = Math.min(1, Math.max(0, Number(progress) || 0));
  let targetIdx = 0;
  for (let i = 0; i < scenes.length; i++) {
    const scPct = typeof scenes[i].timePct === "number" ? scenes[i].timePct : (i / scenes.length);
    if (p >= scPct - 0.002) {
      targetIdx = i;
    } else {
      break;
    }
  }
  return targetIdx;
};

window.saveVovoResumeState = function(weekNum, currentTime, duration, sceneIdx) {
  if (!weekNum) return;
  const t = Number(currentTime) || 0;
  const d = Number(duration) || 0;
  if (t <= 1.5 || (d > 0 && t >= d - 2.5)) return;
  const payload = {
    week: weekNum,
    time: Math.round(t * 10) / 10,
    duration: Math.round(d * 10) / 10,
    pct: d > 0 ? Math.min(1, Math.max(0, t / d)) : 0,
    sceneIdx: typeof sceneIdx === "number" ? sceneIdx : 0,
    updatedAt: Date.now()
  };
  try {
    localStorage.setItem(`trono_ebd_vovo_resume_v78_w${weekNum}`, JSON.stringify(payload));
  } catch (e) {}
};

window.getVovoSavedResume = function(weekNum) {
  if (!weekNum) return null;
  try {
    const raw = localStorage.getItem(`trono_ebd_vovo_resume_v78_w${weekNum}`);
    if (!raw) return null;
    const data = JSON.parse(raw);
    if (data && typeof data.time === "number" && data.time > 1.5) {
      return data;
    }
  } catch (e) {}
  return null;
};

window.clearVovoSavedResume = function(weekNum) {
  if (!weekNum) return;
  try {
    localStorage.removeItem(`trono_ebd_vovo_resume_v78_w${weekNum}`);
  } catch (e) {}
};

window.VOVO_ICON_PLAY_SVG = '<svg width="26" height="26" viewBox="0 0 24 24" fill="#0f172a" style="margin-left:3px; display:block;"><path d="M6 4.5L19.5 12L6 19.5V4.5Z" stroke="#0f172a" stroke-width="1.5" stroke-linejoin="round"/></svg>';
window.VOVO_ICON_PAUSE_SVG = '<svg width="24" height="24" viewBox="0 0 24 24" fill="#0f172a" style="display:block;"><rect x="6" y="4.5" width="4.2" height="15" rx="1.4"/><rect x="13.8" y="4.5" width="4.2" height="15" rx="1.4"/></svg>';

window.setVovoPlayBtnState = function(isPlaying) {
  const playBtnEl = document.getElementById("vovo-play-btn");
  if (!playBtnEl) return;
  playBtnEl.innerHTML = isPlaying ? window.VOVO_ICON_PAUSE_SVG : window.VOVO_ICON_PLAY_SVG;
  playBtnEl.setAttribute("aria-label", isPlaying ? "Pausar história" : "Tocar história");
};

window.updateVovoPlayerTimelineUI = function(lesson, currentTime, duration, isPlaying) {
  const scenes = (lesson && lesson.storyScenes) || [{ img: lesson.thumbImg, caption: lesson.title }];
  const dur = Number(duration) || 0;
  const cur = Math.max(0, Number(currentTime) || 0);
  const progress = dur > 0 ? Math.min(1, Math.max(0, cur / dur)) : 0;
  const pctStr = `${(progress * 100).toFixed(1)}%`;

  const barFillEl = document.getElementById("vovo-video-progress-fill");
  const thumbEl = document.getElementById("vovo-video-progress-thumb");
  const scrubEl = document.getElementById("vovo-video-scrubber");
  const timeCurEl = document.getElementById("vovo-video-time-current");
  const timeTotEl = document.getElementById("vovo-video-time-total");
  const timeLabelEl = document.getElementById("vovo-video-time-label");

  if (barFillEl) barFillEl.style.width = pctStr;
  if (thumbEl) thumbEl.style.left = pctStr;
  if (scrubEl && !window._vovoIsDraggingScrub) {
    scrubEl.value = String(Math.round(progress * 1000));
  }

  const targetScene = window.getVovoSceneIndexForProgress(lesson, progress);
  if (targetScene !== window.EBD_STATE.vovoActiveSceneIdx) {
    window.selectVovoStoryScene(targetScene, true);
  }

  if (timeCurEl) {
    timeCurEl.textContent = window.formatVovoTime(cur);
  }
  if (timeTotEl) {
    timeTotEl.textContent = dur > 0 ? window.formatVovoTime(dur) : "0:00";
  }
  if (timeLabelEl) {
    timeLabelEl.textContent = dur > 0
      ? `${window.formatVovoTime(cur)} / ${window.formatVovoTime(dur)}`
      : `${window.formatVovoTime(cur)}`;
  }
  if (typeof isPlaying === "boolean") {
    window.setVovoPlayBtnState(isPlaying);
  }
};

window.ensureVovoAudioElement = function(lesson) {
  const ageBracket = ["3-5", "6-8"].includes(window.EBD_STATE.ageBracket) ? window.EBD_STATE.ageBracket : "6-8";
  const ageData = (lesson.byAge && lesson.byAge[ageBracket]) || lesson.byAge["6-8"];
  const defaultMp3 = `./6_ASSETS_AUDIO/licoes_vovo/licao_${String(lesson.week).padStart(2, "0")}_vovo.mp3?v=81`;
  const rawSrc = (ageData && ageData.vovoAudioMp3) || lesson.vovoAudioMp3 || defaultMp3;
  const audioSrc = String(rawSrc).split("?")[0] + "?v=78";

  if (window.EBD_STATE.vovoAudioEl && window.EBD_STATE.vovoAudioWeek === lesson.week) {
    const cachedEl = window.EBD_STATE.vovoAudioEl;
    window.updateVovoPlayerTimelineUI(lesson, cachedEl.currentTime || 0, cachedEl.duration || 0, !!window.EBD_STATE.vovoAudioPlaying);
    return cachedEl;
  }

  if (window.EBD_STATE.vovoAudioEl) {
    try { window.EBD_STATE.vovoAudioEl.pause(); } catch (e) {}
  }

  const audio = new Audio(audioSrc);
  audio.preload = "auto";
  window.EBD_STATE.vovoAudioEl = audio;
  window.EBD_STATE.vovoAudioWeek = lesson.week;
  window.EBD_STATE.vovoAudioPlaying = false;

  const saved = window.getVovoSavedResume(lesson.week);
  if (saved && saved.time > 1.5) {
    const applySavedTime = function() {
      if (audio.currentTime < 1 && saved.time < (audio.duration || 9999) - 2) {
        try { audio.currentTime = saved.time; } catch (e) {}
      }
      window.updateVovoPlayerTimelineUI(lesson, audio.currentTime || saved.time, audio.duration || saved.duration, window.EBD_STATE.vovoAudioPlaying);
    };
    if (audio.readyState >= 1) {
      applySavedTime();
    } else {
      audio.addEventListener("loadedmetadata", applySavedTime, { once: true });
    }
  } else {
    audio.addEventListener("loadedmetadata", function() {
      window.updateVovoPlayerTimelineUI(lesson, audio.currentTime || 0, audio.duration || 0, window.EBD_STATE.vovoAudioPlaying);
    }, { once: true });
  }

  audio.ontimeupdate = function() {
    if (!audio.duration) return;
    window.updateVovoPlayerTimelineUI(lesson, audio.currentTime, audio.duration, window.EBD_STATE.vovoAudioPlaying);
    if (!window._lastVovoSaveTs || Date.now() - window._lastVovoSaveTs > 2000) {
      window._lastVovoSaveTs = Date.now();
      window.saveVovoResumeState(lesson.week, audio.currentTime, audio.duration, window.EBD_STATE.vovoActiveSceneIdx);
    }
  };

  audio.onended = function() {
    window.EBD_STATE.vovoAudioPlaying = false;
    window.clearVovoSavedResume(lesson.week);
    try { audio.currentTime = 0; } catch (e) {}
    const imgEl = document.getElementById("vovo-story-scene-img");
    const barFillEl = document.getElementById("vovo-video-progress-fill");
    const thumbEl = document.getElementById("vovo-video-progress-thumb");
    const scrubEl = document.getElementById("vovo-video-scrubber");
    const timeCurEl = document.getElementById("vovo-video-time-current");
    window.setVovoPlayBtnState(false);
    if (imgEl) imgEl.classList.remove("vovo-video-playing-img");
    if (barFillEl) barFillEl.style.width = "100%";
    if (thumbEl) thumbEl.style.left = "100%";
    if (scrubEl) scrubEl.value = "1000";
    if (timeCurEl && audio.duration) timeCurEl.textContent = window.formatVovoTime(audio.duration);
    if (typeof window.markLessonModuleDone === "function" && lesson && lesson.week) {
      window.markLessonModuleDone(lesson.week, "vovo");
    }
  };

  audio.onerror = function() {
    window.EBD_STATE.vovoAudioPlaying = false;
    const imgEl = document.getElementById("vovo-story-scene-img");
    window.setVovoPlayBtnState(false);
    if (imgEl) imgEl.classList.remove("vovo-video-playing-img");
  };

  return audio;
};

window.toggleVovoStoryNarration = function() {
  const lesson = window.getCurrentLessonObj();
  window.preloadVovoLessonImages(lesson);
  const imgEl = document.getElementById("vovo-story-scene-img");

  // 1. Se já está tocando -> PAUSA exatamente no segundo atual e salva no localStorage!
  if (window.EBD_STATE.vovoAudioPlaying && window.EBD_STATE.vovoAudioEl) {
    try {
      window.EBD_STATE.vovoAudioEl.pause();
    } catch (e) {}
    window.EBD_STATE.vovoAudioPlaying = false;
    window.saveVovoResumeState(
      lesson.week,
      window.EBD_STATE.vovoAudioEl.currentTime,
      window.EBD_STATE.vovoAudioEl.duration,
      window.EBD_STATE.vovoActiveSceneIdx
    );
    window.setVovoPlayBtnState(false);
    if (imgEl) imgEl.classList.remove("vovo-video-playing-img");
    return;
  }

  // Pausa música de fundo enquanto o Vovô Nésio conta a história
  if (typeof bgAudioPlayer !== "undefined" && bgAudioPlayer && !bgAudioPlayer.paused) {
    bgAudioPlayer.pause();
  }
  const bgm = document.getElementById("bgm-player");
  if (bgm && !bgm.paused) {
    bgm.pause();
  }

  const audio = window.ensureVovoAudioElement(lesson);
  const saved = window.getVovoSavedResume(lesson.week);
  if (audio.currentTime < 1 && saved && saved.time > 1.5) {
    try { audio.currentTime = saved.time; } catch (e) {}
  }

  window.EBD_STATE.vovoAudioPlaying = true;
  window.setVovoPlayBtnState(true);
  if (imgEl) imgEl.classList.add("vovo-video-playing-img");

  audio.play().catch(() => {
    window.EBD_STATE.vovoAudioPlaying = false;
    window.setVovoPlayBtnState(false);
    if (imgEl) imgEl.classList.remove("vovo-video-playing-img");
  });
};

window.stepVovoStoryTime = function(deltaSeconds) {
  const lesson = window.getCurrentLessonObj();
  window.preloadVovoLessonImages(lesson);
  const audio = window.ensureVovoAudioElement(lesson);
  const saved = window.getVovoSavedResume(lesson.week);
  const dur = audio.duration || (saved && saved.duration) || 195;
  const baseTime = audio.currentTime > 0 ? audio.currentTime : ((saved && saved.time) || 0);
  const nextTime = Math.max(0, Math.min(dur - 0.5, baseTime + Number(deltaSeconds || 0)));

  try {
    audio.currentTime = nextTime;
  } catch (e) {}
  window.updateVovoPlayerTimelineUI(lesson, nextTime, dur, window.EBD_STATE.vovoAudioPlaying);
  window.saveVovoResumeState(lesson.week, nextTime, dur, window.EBD_STATE.vovoActiveSceneIdx);
};

window.onScrubVovoStory = function(sliderVal) {
  const lesson = window.getCurrentLessonObj();
  window.preloadVovoLessonImages(lesson);
  const ratio = Math.min(1, Math.max(0, (Number(sliderVal) || 0) / 1000));
  const audio = window.ensureVovoAudioElement(lesson);
  const saved = window.getVovoSavedResume(lesson.week);
  const dur = audio.duration || (saved && saved.duration) || 195;
  const nextTime = ratio * dur;

  try {
    audio.currentTime = nextTime;
  } catch (e) {}
  window.updateVovoPlayerTimelineUI(lesson, nextTime, dur, window.EBD_STATE.vovoAudioPlaying);
  if (nextTime > 1.5) {
    window.saveVovoResumeState(lesson.week, nextTime, dur, window.EBD_STATE.vovoActiveSceneIdx);
  }
};

window.restartVovoStoryFromZero = function() {
  if (typeof window.ebdClick === "function") window.ebdClick();
  const lesson = window.getCurrentLessonObj();
  window.clearVovoSavedResume(lesson.week);
  const wasPlaying = !!window.EBD_STATE.vovoAudioPlaying;
  const audio = window.ensureVovoAudioElement(lesson);
  try {
    audio.currentTime = 0;
  } catch (e) {}
  window.selectVovoStoryScene(0, true);
  window.updateVovoPlayerTimelineUI(lesson, 0, audio.duration || 0, wasPlaying);
  if (!wasPlaying) {
    window.toggleVovoStoryNarration();
  }
};

window.stopVovoStoryNarration = function(forceReset) {
  if (window.EBD_STATE.vovoAudioEl) {
    const wk = window.EBD_STATE.vovoAudioWeek;
    const cur = window.EBD_STATE.vovoAudioEl.currentTime || 0;
    const dur = window.EBD_STATE.vovoAudioEl.duration || 0;
    try {
      window.EBD_STATE.vovoAudioEl.pause();
    } catch (e) {}
    if (forceReset) {
      try { window.EBD_STATE.vovoAudioEl.currentTime = 0; } catch (e) {}
      window.clearVovoSavedResume(wk);
      window.EBD_STATE.vovoAudioEl = null;
      window.EBD_STATE.vovoAudioWeek = null;
    } else if (cur > 1.5) {
      window.saveVovoResumeState(wk, cur, dur, window.EBD_STATE.vovoActiveSceneIdx);
    }
  }
  window.EBD_STATE.vovoAudioPlaying = false;
  const imgEl = document.getElementById("vovo-story-scene-img");
  if (imgEl) imgEl.classList.remove("vovo-video-playing-img");
  window.setVovoPlayBtnState(false);
};

